<?php
$pagination = $pagination ?? [];
$filters = $filters ?? [];
$pageSize = (int) ($pageSize ?? 15);
$url = static function (string $key, int $page) use ($filters, $pageSize): string {
    $query = array_filter(['search' => $filters['search'] ?? '', 'appointment_status' => $filters['appointment_status'] ?? '', 'page_size' => $pageSize, $key => $page], static fn ($value) => $value !== '' && $value !== null);
    return current_url() . '?' . http_build_query($query);
};
